package ui

const AdminEditorStatsCSS = `.editor-stats{display:flex;gap:1rem;flex-wrap:wrap;padding:.65rem 1rem;color:var(--muted);font-size:.78rem}.editor-stats strong{color:var(--ink);font-variant-numeric:tabular-nums}.editor-stats .is-overused,.seo-audit .is-overused{color:var(--red,#dc2626);font-weight:700}.seo-audit{margin-top:.75rem;padding:.75rem 1rem;color:var(--muted);font-size:.82rem}.seo-audit h2{margin:0 0 .45rem;color:var(--ink);font-size:.95rem}.seo-audit ul{display:grid;gap:.25rem;margin:0;padding-inline-start:1.25rem}`

const AdminEditorStatsJS = `(()=>{const textOf=e=>e?.value??e?.innerText??e?.textContent??'',set=(root,selector,ok,message)=>{const el=root.querySelector(selector);if(el){el.textContent=(ok?'✓ ':'• ')+message;el.classList.toggle('is-overused',!ok)}return ok};const update=()=>{const bar=document.querySelector('[data-editor-stats]'),audit=document.querySelector('[data-seo-audit]');if(!bar||!audit)return;const editor=document.querySelector('.richtext-editor .ql-editor,.richtext-editor[contenteditable="true"],textarea[name="body"]');if(!editor){bar.hidden=true;audit.hidden=true;return}bar.hidden=false;audit.hidden=false;const text=textOf(editor),words=text.trim().match(/\S+/gu)||[];bar.querySelector('[data-editor-words]').textContent=String(words.length);bar.querySelector('[data-editor-characters]').textContent=String(text.length);bar.querySelector('[data-editor-reading-time]').textContent=String(Math.max(1,Math.ceil(words.length/200)));const keyword=document.querySelector('[name="focus_keyword"],[name="keyword"]'),wrap=bar.querySelector('[data-editor-keyword-wrap]');if(keyword?.value.trim()){const needle=keyword.value.trim().toLocaleLowerCase(),matches=words.filter(word=>word.replace(/[^\p{L}\p{N}]/gu,'').toLocaleLowerCase()===needle).length,density=words.length?matches/words.length*100:0;bar.querySelector('[data-editor-keyword-density]').textContent=density.toFixed(1)+'%';wrap.hidden=false;wrap.classList.toggle('is-overused',density>3)}else{wrap.hidden=true;wrap.classList.remove('is-overused')}const title=document.querySelector('[name="seo_title"],[name="title"]'),description=document.querySelector('[name="seo_description"],[name="description"],[name="excerpt"]'),titleLength=Array.from(textOf(title).trim()).length,descriptionLength=Array.from(textOf(description).trim()).length,checks=[];checks.push(set(audit,'[data-seo-title]',titleLength>=30&&titleLength<=60,'Başlık '+titleLength+' karakter (öneri 30–60)'));checks.push(set(audit,'[data-seo-description]',descriptionLength>=120&&descriptionLength<=160,'Açıklama '+descriptionLength+' karakter (öneri 120–160)'));const doc=editor.matches('.ql-editor')?editor:new DOMParser().parseFromString(text,'text/html'),headings=[...doc.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(h=>Number(h.tagName.slice(1))),hasH1=headings.includes(1),skipped=headings.some((n,i)=>i>0&&n>headings[i-1]+1);checks.push(set(audit,'[data-seo-heading]',hasH1&&!skipped,hasH1?(skipped?'Başlık seviyelerinde atlama var':'Başlık yapısı uygun'):'H1 başlığı eksik'));const images=[...doc.querySelectorAll('img')],missingAlt=images.filter(img=>!img.getAttribute('alt')?.trim()).length;checks.push(set(audit,'[data-seo-alt]',missingAlt===0,missingAlt?missingAlt+' görselde açıklama eksik':'Görsel açıklamaları mevcut'));const sentences=text.split(/[.!?]+/u).filter(s=>s.trim()).length,average=sentences?words.length/sentences:words.length;checks.push(set(audit,'[data-seo-readability]',average<=25,average?Math.round(average)+' kelime/cümle ortalaması':'İçerik ekleyin'));audit.querySelector('[data-seo-score]').textContent=checks.filter(Boolean).length+'/5'};document.addEventListener('input',event=>{if(event.target.closest('.richtext-editor,textarea,[name="title"],[name="seo_title"],[name="seo_description"],[name="description"],[name="excerpt"],[name="focus_keyword"],[name="keyword"]'))update()});document.addEventListener('hydro:admin-navigated',update);update()})();`
